css:
.pr-head { border-bottom: 0; position: relative; padding-bottom: 14pt; }
.pr-head::after { content: ''; position: absolute; left: 0; right: 0; bottom: 2pt; height: 7pt; background: repeating-linear-gradient(-45deg, #1C1A1D 0 1.6pt, transparent 1.6pt 4.2pt); }
.pr-head h1, .pr-family-head h1 { font-family: 'Space Grotesk Variable', sans-serif; font-weight: 600; letter-spacing: -0.025em; }
.pr-eyebrow, .pr-p-kind, .pr-sg-kicker, .pr-label { font-family: 'IBM Plex Mono', monospace; font-weight: 600; letter-spacing: 0.05em; color: #1C1A1D; }
.pr-sec-head { border-bottom: 0; position: relative; padding-bottom: 13pt; }
.pr-sec-head::after { content: ''; position: absolute; left: 0; right: 0; bottom: 2pt; height: 6pt; background: repeating-linear-gradient(-45deg, #1C1A1D 0 1.6pt, transparent 1.6pt 4.2pt); }
.pr-sec-head .pr-eyebrow { display: inline-block; background: #1C1A1D; color: #FFFFFF; font-family: 'IBM Plex Mono', monospace; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase; line-height: 1.35; border-radius: 0; box-shadow: -1.2px 0 0 rgba(63,214,230,0.8), 1.2px 0.6px 0 rgba(255,95,168,0.8); font-size: 6.5pt; padding: 2pt 6pt; margin-bottom: 6pt !important; }
.pr-sec-head h2 { font-family: 'Space Grotesk Variable', sans-serif; font-weight: 600; font-size: 30pt; letter-spacing: -0.03em; color: #1C1A1D; }
.pr-p { border-top: 0.75pt solid #E2E0E4; }
.pr-p-head h3, .pr-weeks h3 { font-family: 'Space Grotesk Variable', sans-serif; font-weight: 600; letter-spacing: -0.015em; }
.pr-p-num { font-family: 'Space Grotesk Variable', sans-serif; font-weight: 600; color: #1C1A1D; letter-spacing: -0.04em; }
.pr-p-num::before { content: '+'; }
.pr-m-label { display: inline-block; background: #1C1A1D; color: #FFFFFF; font-family: 'IBM Plex Mono', monospace; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase; line-height: 1.35; border-radius: 0; box-shadow: -1.2px 0 0 rgba(63,214,230,0.8), 1.2px 0.6px 0 rgba(255,95,168,0.8); font-size: 6pt; padding: 1.5pt 4pt; }
.pr-cue { display: inline-block; background: transparent; color: #1C1A1D; border: 1pt solid #1C1A1D; border-radius: 0; font-family: 'IBM Plex Mono', monospace; font-weight: 600; font-size: 6.5pt; letter-spacing: 0.04em; padding: 1pt 4pt; }
.pr-say { border-left: 1.5pt solid #1C1A1D; }
.pr-reading { background: #FFFFFF; border-radius: 0; background-image: none; padding: 12pt 14pt; box-shadow: none; }
.pr-reading, .pr-family-card, .pr-sg-close > div, .pr-roles > div { border: 0; border-radius: 0; background: linear-gradient(#1C1A1D,#1C1A1D) top left / 7pt 1pt no-repeat, linear-gradient(#1C1A1D,#1C1A1D) top left / 1pt 7pt no-repeat, linear-gradient(#1C1A1D,#1C1A1D) top right / 7pt 1pt no-repeat, linear-gradient(#1C1A1D,#1C1A1D) top right / 1pt 7pt no-repeat, linear-gradient(#1C1A1D,#1C1A1D) bottom left / 7pt 1pt no-repeat, linear-gradient(#1C1A1D,#1C1A1D) bottom left / 1pt 7pt no-repeat, linear-gradient(#1C1A1D,#1C1A1D) bottom right / 7pt 1pt no-repeat, linear-gradient(#1C1A1D,#1C1A1D) bottom right / 1pt 7pt no-repeat; }
.pr-tag { display: inline-block; background: #1C1A1D; color: #FFFFFF; font-family: 'IBM Plex Mono', monospace; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase; line-height: 1.35; border-radius: 0; box-shadow: -1.2px 0 0 rgba(63,214,230,0.8), 1.2px 0.6px 0 rgba(255,95,168,0.8); }
.pr-sg-idea > div, .pr-family-strip { background: #1C1A1D; color: #FFFFFF; border-radius: 0; clip-path: polygon(0 0, 100% 0, 100% calc(100% - 14pt), calc(100% - 14pt) 100%, 0 100%); }
.pr-sg-idea .pr-serif, .pr-family-strip p { color: #FFFFFF; font-family: 'Space Grotesk Variable', sans-serif; }
.pr-sg-idea .pr-label { color: #3FD6E6; }
.pr-sg-questions ol { border-top: 1.5pt solid #1C1A1D; }
.pr-sg-questions span, .pr-questions .n { font-family: 'Space Grotesk Variable', sans-serif; font-weight: 600; color: #1C1A1D; }
.pr-sg-notes { background: repeating-linear-gradient(-45deg, #EEECEF 0 6pt, #FFFFFF 6pt 12pt); border-radius: 0; }
.pr-weeks .n { font-family: 'Space Grotesk Variable', sans-serif; color: #1C1A1D; }
.pr-weeks { border-top: 1.5pt solid #1C1A1D; }
.pr-list li::marker, .pr-bullets li::marker { content: '+  '; color: #1C1A1D; font-family: 'IBM Plex Mono', monospace; }
.pr-role-icon, .pr-ico, .pr-family-card-head span { display: none; }
.pr-roles { counter-reset: pf-role; }
.pr-roles > div::before { counter-increment: pf-role; content: '00' counter(pf-role); display: inline-block; background: #1C1A1D; color: #FFFFFF; font-family: 'IBM Plex Mono', monospace; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase; line-height: 1.35; border-radius: 0; box-shadow: -1.2px 0 0 rgba(63,214,230,0.8), 1.2px 0.6px 0 rgba(255,95,168,0.8); font-size: 7pt; padding: 1.5pt 5pt; }
.pr-label:has(+ .pr-legend), .pr-legend { display: none; }
.pr-row { display: block; }
.pr-row-body h4 { font-family: 'IBM Plex Mono', monospace; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; font-size: 8pt; }
.pr-row.inclusion h4, .pr-row.note h4 { color: #1C1A1D; }
.pr-family-card-head b { font-family: 'IBM Plex Mono', monospace; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; font-size: 9pt; }
.pr-ov-sec { border-right-color: #1C1A1D; }
.pr-ov-sec span { color: #1C1A1D; font-family: 'IBM Plex Mono', monospace; }
.pfdv { position: relative; width: 8.5in; height: 11in; overflow: hidden; background: #FFFFFF; }
.pfdv .pf-blk { position: absolute; inset: 0; }
.pfdv .pf-num { position: absolute; left: 3.3in; top: 4.6in; font-family: 'Space Grotesk Variable', sans-serif; font-weight: 600; font-size: 168pt; line-height: 1; letter-spacing: -0.05em; color: #1C1A1D; text-shadow:-1.2pt 0 0 rgba(63,214,230,0.85), 1.2pt 0.5pt 0 rgba(255,95,168,0.85); }
.pfdv .pf-num::before { content: '+00'; }
.pfdv[class~="1"] .pf-num::before { content: '+01'; }
.pfdv[class~="2"] .pf-num::before { content: '+02'; }
.pfdv[class~="3"] .pf-num::before { content: '+03'; }
.pfdv[class~="4"] .pf-num::before { content: '+04'; }
.pfdv[class~="5"] .pf-num::before { content: '+05'; }
.pfdv .pf-bar { position: absolute; left: 3.46in; top: 7.0in; width: 1.62in; height: 17px; background: #1C1A1D; color: #FFFFFF; display: flex; align-items: center; gap: 4pt; padding: 0 6pt; box-sizing: border-box; font-family: 'IBM Plex Mono', monospace; font-weight: 600; font-size: 7pt; letter-spacing: 0.06em; text-transform: uppercase; box-shadow: -1.6px 0 0 rgba(63,214,230,0.85), 1.6px 0.8px 0 rgba(255,95,168,0.85); }
.pfdv .pf-bar span { flex: 1; }
.pfdv .pf-bar i, .pfdv .pf-bar b { width: 6px; height: 6px; border: 1.2px solid #FFFFFF; }
.pfdv .pf-bar b { background: #FFFFFF; }
.pfdv .pf-kick { position: absolute; left: 3.54in; top: 2.56in; font-family: 'IBM Plex Mono', monospace; font-weight: 600; font-size: 7pt; letter-spacing: 0.04em; color: #1C1A1D; text-transform: uppercase; width: 1.4in; line-height: 1.5; }
.pfdv .pf-sub { position: absolute; left: 1.72in; top: 3.62in; width: 3.3in; height: 0.95in; font-size: 30pt; display: flex; align-items: flex-end; }
.pfdv h1 { margin: 0; font-family: 'Space Grotesk Variable', sans-serif; font-weight: 600; font-size: 1em; line-height: 0.95; letter-spacing: -0.02em; color: #1C1A1D; }
.pfdv .pf-idea { position: absolute; left: 1.82in; top: 8.3in; width: 1.42in; height: 0.95in; margin: 0; font-family: 'Space Grotesk Variable', sans-serif; font-weight: 500; font-size: 9.5pt; line-height: 1.35; color: #1C1A1D; }
.pfdv .pf-foot { position: absolute; left: 1.55in; top: 10.12in; font-family: 'Space Grotesk Variable', sans-serif; font-weight: 700; font-size: 10pt; color: #1C1A1D; }
.pfdv .pf-code { position: absolute; left: 5.6in; top: 10.13in; font-family: 'IBM Plex Mono', monospace; font-weight: 600; font-size: 7pt; color: #1C1A1D; text-transform: uppercase; }
.pfdv .pf-a, .pfdv .pf-b, .pfdv .pf-field { transform-box: view-box; transform-origin: 425px 550px; }
.pfdv .pf-title { display: none; position: absolute; left: 1.72in; top: 3.62in; width: 3.3in; height: 0.95in; font-size: 40pt; align-items: flex-end; }
.pfdv:not(.Week) .pf-title { display: flex; }
.pfdv:not(.Week) .pf-sub { display: none; }
.pfdv[class~="2"] .pf-field, .pfdv[class~="2"] .pf-a { transform: scale(-1, 1); }
.pfdv[class~="2"] .pf-blk { transform: translate(3.48in, 0); }
.pfdv[class~="2"] .pf-num { left: 0.5in; }
.pfdv[class~="2"] .pf-bar { left: 1.72in; }
.pfdv[class~="2"] .pf-sub { left: 3.46in; }
.pfdv[class~="2"] .pf-kick { left: 1.8in; }
.pfdv[class~="3"] .pf-field { transform: scale(1, -1); }
.pfdv[class~="3"] .pf-a { transform: translate(0, 480px); }
.pfdv[class~="3"] .pf-b { transform: translate(0, -470px); }
.pfdv[class~="3"] .pf-blk { transform: translate(0, 4.8in); }
.pfdv[class~="3"] .pf-num { top: 0.7in; left: 3.6in; }
.pfdv[class~="3"] .pf-bar { top: 3.0in; left: 5.2in; }
.pfdv[class~="3"] .pf-sub { top: 8.5in; left: 3.46in; }
.pfdv[class~="3"] .pf-kick { top: 7.3in; }
.pfdv[class~="3"] .pf-idea { top: 4.0in; left: 5.28in; }
.pfdv[class~="4"] .pf-a { transform: translate(174px, 0); }
.pfdv[class~="4"] .pf-blk { transform: translate(1.74in, 0); }
.pfdv[class~="4"] .pf-num { top: 7.6in; left: 0.3in; }
.pfdv[class~="4"] .pf-bar { top: 5.6in; left: 5.2in; }
.pfdv[class~="4"] .pf-sub { left: 0.2in; top: 3.62in; width: 3.2in; }
.pfdv[class~="4"] .pf-idea { left: 5.28in; top: 6.0in; }
.pfdv[class~="5"] .pf-field, .pfdv[class~="5"] .pf-a, .pfdv[class~="5"] .pf-b { transform: scale(-1, -1); }
.pfdv[class~="5"] .pf-blk { transform: translate(3.48in, 5.2in); }
.pfdv[class~="5"] .pf-num { top: 1.1in; left: 0.5in; }
.pfdv[class~="5"] .pf-bar { top: 3.3in; left: 1.72in; }
.pfdv[class~="5"] .pf-sub { top: 3.9in; left: 3.46in; }
.pfdv[class~="5"] .pf-idea { top: 6.4in; left: 5.28in; }
